import numpy as np

def avg_psd(x, n):
    m = len(x) // n
    if m == 0:
        raise ValueError('signal shorter than one frame')
    frames = x[:m * n].reshape(m, n)          # view, no copy
    w = np.hanning(n).astype(np.float32)      # keep complex64
    X = np.fft.fft(frames * w, axis=1)        # broadcast (m,n)*(n,)
    p = X.real**2 + X.imag**2                 # avoids sqrt of abs
    return p.mean(axis=0)
